# K, B, P, Q, C, R, S, H, W, GROUP, STRIDE

[connected]
# 64, 64, 1, 1, 64, 1, 1, 0, 0, 1, 1,
# P2-2: output-channel (K) split 32/32 across the same 2-chip grid as
# configs/mappings/gemmini_2chip/. The weight tile DOES depend on K, so each chip needs
# its own distinct weight chunk -- the mirror image of the B-split fixture, where the
# weight tile is identical on both chips and its NoP source read is shared. Everything
# else (total work, per-chip tile volumes, link transactions) is held constant.
MAC     = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE      = 2, 64, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE_X    = 16, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE_Y    = 1, 1, 1, 1, 16, 1, 1, 0, 0, 1, 1,
GLB     = 1, 1, 1, 1, 4, 1, 1, 0, 0, 1, 1,
CHIPS_X = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
CHIPS_Y = 2, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
DRAM    = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
